// Pega o CSV como 
const input = $input.first().json;
const csvRaw = input.data ?? input.body ?? input;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza minimo para numero
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;                                                 
});

return [{ json: { investimentos } }];

// Recebe do Merge: body.clientes (Webhook) + investimentos (CSV)
const data = $input.first().json;
const clientes = (data.body && data.body.clientes) || data.clientes || [];
const investimentos = data.investimentos || [];

// Estimativa de IPCA anual usada para comparar produtos IPCA+ com prefixados
const IPCA_ESTIMADO = 4.5;

// "R$ 12.500,00" -> 12500
function parseSaldo(s) {
  if (typeof s === 'number') return s;
  const limpo = String(s || '').replace(/[^\d,]/g, '').replace(',', '.');
  return Number(limpo) || 0;
}

// "13.0%" -> 13 | "IPCA+6.0%" -> 10.5 | "Variável" -> null
function rentabilidadeEstimada(r) {
  const txt = String(r || '');
  const num = parseFloat(txt.replace(/[^\d.]/g, ''));
  if (/ipca/i.test(txt)) return IPCA_ESTIMADO + (isNaN(num) ? 0 : num);
  if (txt.indexOf('%') >= 0 && !isNaN(num)) return num;
  return null;
}

const justificativas = {
  conservador: 'Perfil conservador: prioriza segurança e liquidez, então foi escolhida a opção de renda fixa com maior rentabilidade dentro do saldo.',
  moderado: 'Perfil moderado: aceita um pouco mais de risco por retorno maior, então foi escolhida a opção com maior rentabilidade estimada dentro do saldo.',
  arrojado: 'Perfil arrojado: busca crescimento no longo prazo em renda variável; fundos e ETFs diversificados têm prioridade sobre criptomoedas, que ficam como complemento.'
};

function formatBRL(v) {
  return 'R$ ' + v.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const recomendacoes = clientes.map(cliente => {
  const saldo = parseSaldo(cliente.saldo);
  const perfil = String(cliente.perfil || '').trim();
  const perfilKey = perfil.toLowerCase();

  const doPerfil = investimentos.filter(inv => String(inv.perfil || '').toLowerCase() === perfilKey);
  const acessiveis = doPerfil.filter(inv => Number(inv.minimo) <= saldo);

  if (doPerfil.length === 0) {
    return { nome: cliente.nome, email: cliente.email, perfil, saldo: cliente.saldo,
      recomendacao: null, alternativas: [],
      justificativa: 'Nenhum produto cadastrado para o perfil informado.' };
  }

  if (acessiveis.length === 0) {
    const menor = doPerfil.slice().sort((a, b) => a.minimo - b.minimo)[0];
    return { nome: cliente.nome, email: cliente.email, perfil, saldo: cliente.saldo,
      recomendacao: null, alternativas: [],
      justificativa: 'Saldo insuficiente para os produtos do perfil. A opção mais acessível é ' + menor.produto + ' (mínimo ' + formatBRL(menor.minimo) + ').' };
  }

  const ordenados = acessiveis.slice().sort((a, b) => {
    const ra = rentabilidadeEstimada(a.rentabilidade);
    const rb = rentabilidadeEstimada(b.rentabilidade);
    if (ra !== null && rb !== null) return rb - ra;
    if (ra !== null) return -1;
    if (rb !== null) return 1;
    // Renda variável: cripto por último, depois maior aporte mínimo (gestão mais diversificada) primeiro
    const ca = /cripto/i.test(a.produto) ? 1 : 0;
    const cb = /cripto/i.test(b.produto) ? 1 : 0;
    if (ca !== cb) return ca - cb;
    return b.minimo - a.minimo;
  });

  const melhor = ordenados[0];
  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil,
    saldo: cliente.saldo,
    recomendacao: {
      produto: melhor.produto,
      minimo: melhor.minimo,
      rentabilidade: melhor.rentabilidade
    },
    alternativas: ordenados.slice(1).map(i => i.produto),
    justificativa: justificativas[perfilKey] || 'Opção com melhor rentabilidade dentro do saldo disponível.'
  };
});

return [{ json: { total_clientes: recomendacoes.length, recomendacoes } }];

// Transforma as recomendacoes em uma tabela: uma linha (item) por cliente
const data = $input.first().json;
const recomendacoes = data.recomendacoes || [];

function formatBRL(v) {
  return 'R$ ' + Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const linhas = recomendacoes.map(r => {
  const rec = r.recomendacao || {};
  return {
    json: {
      'Cliente': r.nome || '',
      'E-mail': r.email || '',
      'Perfil': r.perfil || '',
      'Saldo': r.saldo || '',
      'Investimento Recomendado': rec.produto || 'Sem recomendação',
      'Aporte Mínimo': rec.produto ? formatBRL(rec.minimo) : '-',
      'Rentabilidade': rec.rentabilidade || '-',
      'Alternativas': (r.alternativas || []).join(', ') || '-',
      'Justificativa': r.justificativa || ''
    }
  };
});

return linhas;

