// Lê o JSON do ChatGPT e monta um e-mail padronizado para o Gmail
// Entrada: 1 item por cliente vindo de "Message a model"
// Os dados do cliente vêm do nó "Montar Tabela" (mesma posição do item)

const respostas = $input.all();
let clientes = [];
try { clientes = $('Montar Tabela').all(); } catch (e) { clientes = []; }

const ASSUNTO_PADRAO = 'Sua recomendação de investimento';
const ASSINATURA = 'Equipe de Investimentos';
const AVISO = 'Esta mensagem tem caráter informativo e não constitui garantia de rentabilidade. Rentabilidade passada não garante resultados futuros.';

// Pega o texto da resposta do ChatGPT em qualquer formato conhecido
function extrairConteudo(j) {
  if (j && j.output && j.output[0] && j.output[0].content && j.output[0].content[0]) {
    return j.output[0].content[0].text;
  }
  if (j && j.message && j.message.content !== undefined) return j.message.content;
  if (j && j.text !== undefined) return j.text;
  if (j && j.content !== undefined) return j.content;
  return j;
}

// Converte em objeto: aceita objeto pronto, JSON puro ou JSON dentro de bloco de código
function parseJson(conteudo) {
  if (conteudo && typeof conteudo === 'object') return conteudo;
  let txt = String(conteudo || '').trim();
  txt = txt.replace(/^\s*[\x60]{3}(?:json)?\s*/i, '').replace(/\s*[\x60]{3}\s*$/, '').trim();
  try { return JSON.parse(txt); } catch (e) {}
  const ini = txt.indexOf('{');
  const fim = txt.lastIndexOf('}');
  if (ini >= 0 && fim > ini) {
    try { return JSON.parse(txt.slice(ini, fim + 1)); } catch (e) {}
  }
  return { text_body: txt };
}

function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function limparTexto(s) {
  return String(s || '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizarAssunto(s) {
  let a = String(s || '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
  a = a.replace(/^(assunto|subject)\s*:\s*/i, '');
  if (!a) a = ASSUNTO_PADRAO;
  if (a.length > 120) a = a.slice(0, 117).trim() + '...';
  return a;
}

function normalizarEmail(s) {
  return String(s || '').trim().toLowerCase();
}

function emailValido(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
}

function textoParaHtml(txt) {
  return limparTexto(txt)
    .split(/\n\n/)
    .map(p => '<p style="margin:0 0 12px 0;">' + escapeHtml(p).replace(/\n/g, '<br>') + '</p>')
    .join('');
}

// Remove estruturas que não devem ir dentro do corpo (html/head/body/script/style)
function limparHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<\/?(html|head|body)[^>]*>/gi, '')
    .replace(/<!doctype[^>]*>/gi, '')
    .trim();
}

function htmlParaTexto(html) {
  return limparTexto(String(html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&'));
}

// Moldura visual única para todos os e-mails
function montarHtml(conteudo, cliente) {
  const rec = cliente['Investimento Recomendado'];
  const resumo = rec && rec !== 'Sem recomendação'
    ? '<table role="presentation" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;margin:16px 0;font-size:14px;">'
      + '<tr style="background:#f3f6fb;"><td style="border:1px solid #dde3ec;"><b>Perfil</b></td><td style="border:1px solid #dde3ec;">' + escapeHtml(cliente['Perfil']) + '</td></tr>'
      + '<tr><td style="border:1px solid #dde3ec;"><b>Investimento</b></td><td style="border:1px solid #dde3ec;">' + escapeHtml(rec) + '</td></tr>'
      + '<tr style="background:#f3f6fb;"><td style="border:1px solid #dde3ec;"><b>Aporte mínimo</b></td><td style="border:1px solid #dde3ec;">' + escapeHtml(cliente['Aporte Mínimo']) + '</td></tr>'
      + '<tr><td style="border:1px solid #dde3ec;"><b>Rentabilidade</b></td><td style="border:1px solid #dde3ec;">' + escapeHtml(cliente['Rentabilidade']) + '</td></tr>'
      + '</table>'
    : '';
  return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:#222;max-width:600px;">'
    + conteudo
    + resumo
    + '<p style="margin:16px 0 0 0;">Atenciosamente,<br>' + escapeHtml(ASSINATURA) + '</p>'
    + '<hr style="border:none;border-top:1px solid #ddd;margin:20px 0 8px 0;">'
    + '<p style="font-size:12px;color:#777;margin:0;">' + escapeHtml(AVISO) + '</p>'
    + '</div>';
}

return respostas.map((item, i) => {
  const cliente = (clientes[i] && clientes[i].json) || {};
  const dados = parseJson(extrairConteudo(item.json));

  const nome = String(cliente['Cliente'] || '').trim();
  const to = normalizarEmail(dados.to || dados.email || cliente['E-mail']);
  const subject = normalizarAssunto(dados.subject || dados.assunto);

  let corpoHtml = limparHtml(dados.html_body || dados.html || '');
  let texto = limparTexto(dados.text_body || dados.text || dados.body || dados.corpo || '');
  // Remove a despedida/assinatura gerada pelo ChatGPT (a assinatura padrão é adicionada depois)
  corpoHtml = corpoHtml
    .replace(/<p[^>]*>\s*(atenciosamente|cordialmente|abraços|um abraço|saudações)[\s\S]*$/i, '')
    .replace(/\[(seu nome|nome)\]/gi, '')
    .trim();
  texto = texto
    .replace(/\n\s*(atenciosamente|cordialmente|abraços|um abraço|saudações)[\s\S]*$/i, '')
    .replace(/\[(seu nome|nome)\]/gi, '')
    .trim();

  if (!corpoHtml && texto) corpoHtml = textoParaHtml(texto);
  if (!texto && corpoHtml) texto = htmlParaTexto(corpoHtml);
  if (!corpoHtml) {
    texto = 'Olá' + (nome ? ', ' + nome : '') + '.\n\nSegue abaixo a recomendação de investimento de acordo com o seu perfil.';
    corpoHtml = textoParaHtml(texto);
  }

  const html = montarHtml(corpoHtml, cliente);
  const text = texto + '\n\nAtenciosamente,\n' + ASSINATURA + '\n\n' + AVISO;

  return {
    json: {
      to,
      email_valido: emailValido(to),
      nome,
      subject,
      html,
      text
    },
    pairedItem: { item: i }
  };
});
